SELECT COUNT(1)
FROM swm_beacon_station a
WHERE a.beacon_id = #{beaconId}
AND a.status = '0' 

    AND a.id != #{id}

SELECT 
    *
FROM swm_beacon_station a
WHERE a.status = '0' 

    AND a.gps_longitude >= #{minLongitude}


    AND a.gps_longitude <= #{maxLongitude}


    AND a.gps_latitude >= #{minLatitude}


    AND a.gps_latitude <= #{maxLatitude}

ORDER BY a.update_date DESC

SELECT 
    *
FROM swm_beacon_station a
WHERE a.status = '0' 

    AND a.pixel_x >= #{minX}


    AND a.pixel_x <= #{maxX}


    AND a.pixel_y >= #{minY}


    AND a.pixel_y <= #{maxY}

ORDER BY a.update_date DESC

