mapper.select:
SELECT * FROM swm_beacon_station a WHERE a.status = '0' AND a.beacon_type = '3' AND NOT EXISTS ( SELECT 1 FROM swm_hazard_source h WHERE h.status = '0'
AND h.id != #{excludeHazardSourceId}
AND ( h.beacon_identifier = a.beacon_id OR h.beacon_identifier LIKE CONCAT(a.beacon_id, ',%') OR h.beacon_identifier LIKE CONCAT('%,', a.beacon_id, ',%') OR h.beacon_identifier LIKE CONCAT('%,', a.beacon_id) ) ) ORDER BY a.update_date DESC
